fullAnalysis:
function FullAnalysis({ result, report }: { result: Result; report: ReturnType<typeof buildProfileReport> }) {
  const topVerb = report.topAreas.length === 1 ? "Det här var ditt starkaste relativa område" : "De här områdena delade högsta relativa resultat";
  const bottomVerb = report.bottomAreas.length === 1 ? "Det här området låg lägst relativt i din profil" : "De här områdena delade lägsta relativa resultat";
  return <div className="space-y-6"><section className={section} aria-labelledby="result-heading"><p className="text-sm font-semibold uppercase tracking-[.14em] text-[#27666A]">Din fullständiga kognitiva profil</p><h2 id="result-heading" className="text-3xl font-semibold">IQ-estimat: {result.iqEstimate}</h2><p className="text-lg">{report.evennessText}</p><p className="text-sm text-neutral-600">Analysen beskriver hur du löste just de här uppgifterna. Den är inte ett normerat, officiellt eller kliniskt IQ-test.</p></section><section className={section}><div><p className="text-sm font-semibold uppercase tracking-[.14em] text-[#27666A]">Din kognitiva profil</p><h2 className="text-2xl font-semibold">Fem områden, ett tydligare sammanhang</h2><p className="text-sm text-neutral-600">Varje poäng är normaliserad inom testet och jämförs här bara med dina egna övriga områden.</p></div><div className="grid gap-3 sm:grid-cols-2">{report.areaReports.map(item => <article key={item.area} className="min-w-0 rounded-2xl border border-neutral-200 bg-neutral-50 p-4"><div className="flex items-start justify-between gap-3"><h3 className="font-semibold">{areaNames[item.area]}</h3><strong className="shrink-0 tabular-nums">{item.score}/100</strong></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-neutral-200"><div className="h-full rounded-full bg-[#27666A]" style={{ width: `${item.score}%` }} /></div><p className="mt-3 text-sm leading-6">{item.interpretation}</p><p className="mt-2 text-xs leading-5 text-neutral-600"><strong>Uppgifterna testade:</strong> {item.explanation}.</p></article>)}</div></section><section className={section}><p className="text-sm font-semibold uppercase tracking-[.14em] text-[#27666A]">Relativa styrkor</p><h2 className="text-2xl font-semibold">{topVerb}</h2><p><strong>{report.topAreaNames}</strong> {report.topAreas.length === 1 ? "hade högst normaliserade resultat" : "hade samma högsta normaliserade resultat"} i just det här testet.</p><p className="text-sm text-neutral-600">Uppgifterna där handlade om {report.topAreas.map(area => areaNames[area].toLocaleLowerCase("sv-SE")).join(" och ")}. Skillnaden till profilens lägsta resultat var {result.spread} poäng.</p></section><section className={section}><p className="text-sm font-semibold uppercase tracking-[.14em] text-[#27666A]">Relativt svagare områden</p><h2 className="text-2xl font-semibold">{bottomVerb}</h2><p><strong>{report.bottomAreaNames}</strong> {report.bottomAreas.length === 1 ? "låg" : "låg"} lägre än flera av dina övriga områden i testet.</p><p className="text-sm text-neutral-600">Det är en jämförelse inom just denna uppsättning uppgifter, inte ett omdöme om din allmänna förmåga.</p></section><section className={section}><p className="text-sm font-semibold uppercase tracking-[.14em] text-[#27666A]">Profilens jämnhet</p><h2 className="text-2xl font-semibold">{report.evennessLabel}</h2><p>{report.evennessText}</p><p className="text-sm text-neutral-600">Största skillnaden mellan två områden var {result.spread} poäng.</p></section><section className={section}><p className="text-sm font-semibold uppercase tracking-[.14em] text-[#27666A]">Personliga resultatinsikter</p><h2 className="text-2xl font-semibold">Mönster i just dina svar</h2><ul className="space-y-3">{report.insights.map(insight => <li key={insight} className="rounded-xl bg-neutral-50 p-3 text-sm leading-6">{insight}</li>)}</ul></section><section className={section}><h2 className="text-2xl font-semibold">Samma IQ-estimat – olika profiler</h2><p>Två personer kan få samma IQ-estimat trots att deras resultat ser olika ut. En person kan ha sina högsta resultat på språk och logik, medan en annan har högre resultat på visuella och spatiala uppgifter. Därför ger profilen mer sammanhang än totalsiffran ensam.</p></section><section className={section}><h2 className="text-2xl font-semibold">Så byggdes ditt resultat</h2><p>Testet innehåller 40 frågor fördelade över fem kognitiva områden. Uppgifterna har olika svårighetsgrad och vikt i testets befintliga sammanvägning. Dina resultat inom områdena normaliseras inom testet och den viktade prestationen vägs sedan samman till ditt IQ-estimat.</p><p className="text-sm text-neutral-600">Sömn, stress, språk, vana vid formatet och testsituation kan påverka hur man löser uppgifterna.</p></section></div>;
}

functions.choose:
function choose(value: number) {
    if (answerLock.current) return;
    answerLock.current = true; setTransitioning(true);
    const next = answers.map((answer, position) => position === index ? value : answer); const nextTimes = responseTimes.map((time, position) => position === index ? Math.max(0, Math.round((Date.now() - startedQuestionAt.current) / 1000)) : time);
    tracking.answer(answered + (answers[index] < 0 ? 1 : 0), index + 1); setAnswers(next); setResponseTimes(nextTimes); setEditing(true);
    timer.current = setTimeout(() => { moveFocus.current = true; if (index < questions.length - 1) { setIndex(index + 1); startedQuestionAt.current = Date.now(); } else if (next.every(answer => answer >= 0)) { setEditing(false); setAnalysisStep(0); setAnalysing(true); } else { const nextIndex = next.findIndex(answer => answer < 0); setIndex(nextIndex); startedQuestionAt.current = Date.now(); } answerLock.current = false; setTransitioning(false); timer.current = null; }, 220);
  }

functions.checkout:
function checkout() {
    const checkoutState = { version: STATE_VERSION, index, answers, unlocked, responseTimes };
    if (!payment.prepareCheckout(checkoutState)) return;
    if (!IQ_TEST_STRIPE_URL.startsWith("https://buy.stripe.com/")) { setCheckoutUnavailable(true); return; }
    tracking.checkout(() => { window.location.assign(IQ_TEST_STRIPE_URL); });
  }

effects:
useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- synchronizes browser-only persisted test state after hydration.
    try { const saved = parseState(localStorage.getItem(STORAGE_KEY)); if (saved) { setAnswers(saved.answers); setIndex(saved.index); setUnlocked(saved.unlocked); setResponseTimes(saved.responseTimes); } }
    catch { setStorageUnavailable(true); }
    if (new URLSearchParams(window.location.search).get("paid") === "true") { purchaseEvent("iq_test"); setUnlocked(true); window.history.replaceState({}, "", window.location.pathname); }
    startedQuestionAt.current = Date.now(); setHydrated(true);
  }, [])

useEffect(() => {
    if (!analysing) return;
    const timers = [setTimeout(() => setAnalysisStep(1), 1000), setTimeout(() => setAnalysisStep(2), 2200), setTimeout(() => { moveFocus.current = true; setAnalysing(false); }, 3600)];
    return () => timers.forEach(clearTimeout);
  }, [analysing])
